"""Build an offline private review atlas; reads retained results, runs no producer."""
from pathlib import Path
import base64
import hashlib
import html
import json
import re
import sys

ROOT=Path(__file__).resolve().parents[1]
if (ROOT/'test-deps').exists():sys.path.insert(0,str(ROOT/'test-deps'))
import markdown


def read(name):return json.loads((ROOT/name).read_text())
def safe(value):return json.dumps(value,ensure_ascii=False).replace('<','\\u003c').replace('&','\\u0026')
def picture(path):return 'data:image/png;base64,'+base64.b64encode(path.read_bytes()).decode()
def md(name,prefix='review-'):
    rendered=markdown.markdown((ROOT/name).read_text(),extensions=['tables','fenced_code','toc'])
    rendered=re.sub(r'id="([^"]+)"',lambda m:'id="'+prefix+m.group(1)+'"',rendered)
    return re.sub(r'href="#([^"]+)"',lambda m:'href="#'+prefix+m.group(1)+'"',rendered)


